LANG = {"tam_Taml": "tam", "mal_Mlym": "mal", "tel_Telu": "tel", "kan_Knda": "kan", "hin_Deva": "hin", "ben_Beng": "ben"}
UA = {"User-Agent": "invent7-validity-check/0.1 (research; github.com/novain-shibu)"}
def log(m): print(f"[{time.time()-T0:7.1f}s] {m}", flush=True)
def warc_payload(fp, off):
    req = urllib.request.Request("https://data.commoncrawl.org/" + fp, headers={**UA, "Range": f"bytes={off}-{off + 60_000_000}"})
    d = zlib.decompressobj(16 + zlib.MAX_WBITS); buf = io.BytesIO()
    with urllib.request.urlopen(req, timeout=120) as r:
        while not d.eof:
            c = r.read(65536)
            if not c: break
            buf.write(d.decompress(c))
    raw = buf.getvalue(); i = raw.find(b"\r\n\r\n"); j = raw.find(b"\r\n\r\n", i + 4)
    return raw[j + 4:] if raw[:4] == b"WARC" and j > 0 else b""
def ocr(args):
    path, pno, tl = args
    import pymupdf
    try:
        png = f"{path}_{pno}.png"; pymupdf.open(path)[pno].get_pixmap(dpi=300).save(png)
        r = subprocess.run(["tesseract", png, "stdout", "-l", f"{tl}+eng", "--psm", "3"], capture_output=True, text=True,
                           timeout=180, env=dict(os.environ, OMP_THREAD_LIMIT="1"))
        os.remove(png); return pno, r.stdout
    except Exception as e:
        return pno, ""
def main():
    pk = " ".join(f"tesseract-ocr-{t}" for t in set(LANG.values()))
    subprocess.run(f"apt-get -qq update && DEBIAN_FRONTEND=noninteractive apt-get -qq install -y tesseract-ocr {pk}", shell=True)
    subprocess.run(f"{sys.executable} -m pip install -q pymupdf", shell=True)
    import pymupdf
    os.makedirs("/kaggle/working/pdf", exist_ok=True); res = {}
    order = sorted(LIST, key=lambda m: (LIST.index(m) % 25, m["cfg"]))  # round-robin over configs
    with ProcessPoolExecutor(max_workers=os.cpu_count() or 4) as ex:
        for k, m in enumerate(order):
            if time.time() - T0 > CAP: log("cap"); break
            try:
                pdf = warc_payload(m["file_path"], m["cc_offset"]); time.sleep(3)
                if not pdf.startswith(b"%PDF"): res[m["id"]] = {"err": "notpdf"}; continue
                p = f"/kaggle/working/pdf/{k}.pdf"; open(p, "wb").write(pdf)
                n = min(10, len(pymupdf.open(p)))
                pages = dict(ex.map(ocr, [(p, i, LANG[m["cfg"]]) for i in range(n)], timeout=CAP))
                res[m["id"]] = {"cfg": m["cfg"], "pages": [pages.get(i, "") for i in range(n)]}
                os.remove(p)
            except Exception as e:
                res[m["id"]] = {"err": repr(e)[:120]}
            json.dump(res, open(OUT, "w"), ensure_ascii=False)
            if k % 10 == 0: log(f"{k}/{len(order)} docs")
    json.dump(res, open(OUT, "w"), ensure_ascii=False); log("done")
if __name__ == "__main__":
    main()
